# hypothesis: periodic in (r mod p, c mod p). Find period.
def periodic_test(A,p):
    seen={}; 
    for r in range(len(A)):
        for c in range(len(A[0])):
            v=A[r][c]
            if v==0: continue
            k=(r%p,c%p)
            if k in seen and seen[k]!=v: return False
            seen[k]=v
    return True
