from collections import Counter
def transform(grid):
    H=len(grid); W=len(grid[0])
    # infer stripe cycle from interior known cells (r,c>=3): value per (r+c) mod p
    # find p: number of distinct interior values, candidates 5 or 7 etc.
    inter=[grid[r][c] for r in range(3,H) for c in range(3,W) if grid[r][c]!=0]
    vals=sorted(set(inter))
    best=None
    for p in range(2,11):
        cyc={}; ok=True
        for k in range(p):
            cnt=Counter(grid[r][c] for r in range(3,H) for c in range(3,W)
                        if (r+c)%p==k and grid[r][c]!=0)
            if not cnt: ok=False; break
            cyc[k]=cnt.most_common(1)[0][0]
        if ok and len(set(cyc.values()))==p:
            score=sum(1 for r in range(3,H) for c in range(3,W)
                      if grid[r][c]!=0 and grid[r][c]==cyc[(r+c)%p])
            if best is None or score>best[0]: best=(score,p,[cyc[k] for k in range(p)])
    _,p,cyc=best
    out=[row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            if out[r][c]==0:
                if r<2 or c<2: out[r][c]=1
                elif r==2 or c==2: out[r][c]=4
                else: out[r][c]=cyc[(r+c)%p]
    return out
